using System.Collections;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "LoseHeartAction", menuName = "Data/Battle/Battle Actions/LoseHeart Action")]
public class LoseHeartAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private VoidEvent OnLoseHeartAction;

	[SerializeField]
	private bool astreasWrath;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float VFXDelay;

	public override void Cast(GameObject source)
	{
		if (IsVFXEnabled())
		{
			if (astreasWrath)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.SetPlayerLoseHeartCoroutine(VFXCoroutine(source));
			}
			else
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(source));
			}
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else if (astreasWrath)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
			{
				if (ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.IsAnyEnemyActive())
				{
					OnLoseHeartAction.Raise();
				}
			});
		}
		else
		{
			OnLoseHeartAction.Raise();
		}
	}

	private IEnumerator VFXCoroutine(GameObject source)
	{
		if (!astreasWrath || ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.IsAnyEnemyActive())
		{
			PlaySFX();
			SpawnVFX(GetVFXOwnerPosition(source), 5f);
			if (enableVFXDelay)
			{
				yield return new WaitForSeconds(VFXDelay);
			}
			OnLoseHeartAction.Raise();
			yield return InvokeAlternatives.WaitOneFrame();
		}
	}
}
